    <select data-player-rate aria-label="\u9ED8\u8BA4\u64AD\u653E\u500D\u901F" hidden>${[.5,.75,1,1.25,1.5,2].map(g=>`<option value="${g}" ${g===e.playbackRate?"selected":""}>${g}\xD7</option>`).join("")}</select>
