    <div class="settings-segmented">${[[0,"\u5173\u95ED"],[60,"60\u79D2"],[90,"90\u79D2"],[120,"120\u79D2"]].map(([g,v])=>`<button type="button" class="${e.skipOutroSeconds===g?"active":""}" data-act="skip-outro-setting" data-id="${g}" aria-pressed="${e.skipOutroSeconds===g}">${v}</button>`).join("")}</div>
